from collections import deque

def get_connected_regions(grid, target=5):
    rows, cols = len(grid), len(grid[0])
    visited = [[False]*cols for _ in range(rows)]
    regions = []

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == target and not visited[r][c]:
                region = []
                queue = deque([(r,c)])
                visited[r][c] = True
                while queue:
                    cr, cc = queue.popleft()
                    region.append((cr, cc))
                    for dr, dc in [(0,1), (0,-1), (1,0), (-1,0)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if grid[nr][nc] == target and not visited[nr][nc]:
                                visited[nr][nc] = True
                                queue.append((nr, nc))
                regions.append(sorted(region, key=lambda x: (x[0], x[1])))
    return regions

regions = get_connected_regions(grid)
print(f"\nNumber of connected regions of 5s: {len(regions)}")
for i, region in enumerate(regions):
